/* ==================== COLORS ==================== */
    
    /* Neutral / Background */
    --bg-primary: #0f0f23;
    --bg-secondary: #1a1a2e;
    --bg-tertiary: #16213e;
    --bg-elevated: #232342;
    --bg-hover: rgba(255, 255, 255, 0.05);
    --bg-active: rgba(255, 255, 255, 0.08);
    
    /* Borders */
    --border-color: #2a2a4a;
    --border-hover: #3a3a5a;
    --border-focus: var(--accent);
    
    /* Text */
    --text-primary: #ffffff;
    --text-secondary: #a0a0b0;
    --text-muted: #9999ad;
    --text-inverse: #0f0f23;
    --text-link: var(--accent-text);
    
    /* Accent (default: Indigo) */
    --accent: #6366f1;
    --accent-hover: #5558e8;
    --accent-light: rgba(99, 102, 241, 0.12);
    --accent-medium: color-mix(in srgb, var(--accent) 25%, transparent);
    
    /* Semantic Colors */
    --success: #10b981;
    --success-light: rgba(16, 185, 129, 0.12);
    --warning: #f59e0b;
    --warning-light: rgba(245, 158, 11, 0.12);
    --danger: #ef4444;
    --danger-light: rgba(239, 68, 68, 0.12);
    --info: #3b82f6;
    --info-light: rgba(59, 130, 246, 0.12);
    
    /* Priority Colors */
    --priority-high: #ef4444;
    --priority-medium: #f59e0b;
    --priority-low: #6b7280;
    
    /* Status Colors */
    --status-backlog: #6b7280;
    --status-progress: #3b82f6;
    --status-review: #f59e0b;
    --status-done: #10b981;
    --status-hold: #8b5cf6;
    
    /* Team Colors */
    --team-indigo: #6366f1;
    --team-emerald: #10b981;
    --team-amber: #f59e0b;
    --team-rose: #f43f5e;
    --team-sky: #0ea5e9;
    --team-violet: #8b5cf6;
    --team-cyan: #06b6d4;
    --team-orange: #f97316;
    --team-teal: #14b8a6;
    --team-purple: #a855f7;
    
    /* ==================== TYPOGRAPHY ==================== */
    --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
    
    --text-xs: 0.75rem;
    --text-sm: 0.875rem;
    --text-base: 1rem;
    --text-lg: 1.125rem;
    --text-xl: 1.25rem;
    --text-2xl: 1.5rem;
    --text-3xl: 1.875rem;
    
    --font-normal: 400;
    --font-medium: 500;
    --font-semibold: 600;
    --font-bold: 700;

    /* Approved typography roles, 19.10.2026. Dense charts are the only 11px text role. */
    --type-page-size: 24px;
    --type-page-line: 30px;
    --type-confirm-size: 16px;
    --type-confirm-line: 22px;
    --type-dialog-size: 18px;
    --type-dialog-line: 24px;
    --type-workspace-size: 20px;
    --type-workspace-line: 26px;
    --type-body-size: 14px;
    --type-body-line: 21px;
    --type-meta-size: 12px;
    --type-meta-line: 18px;
    --type-chart-size: 11px;

    --line-height-tight: 1.25;
    --line-height-normal: 1.5;
    --line-height-relaxed: 1.75;
    
    /* ==================== SPACING ==================== */
    --space-1: 0.25rem;
    --space-2: 0.5rem;
    --space-3: 0.75rem;
    --space-4: 1rem;
    --space-5: 1.25rem;
    --space-6: 1.5rem;
    --space-8: 2rem;
    --space-10: 2.5rem;
    --space-12: 3rem;
    --space-16: 4rem;
    --space-20: 5rem;
    
    /* ==================== BORDERS & RADII ==================== */
    --radius-sm: 4px;
    --radius-md: 8px;
    --radius-lg: 12px;
    --radius-xl: 16px;
    --radius-full: 9999px;
    
    --border-width: 1px;
    
    /* ==================== SHADOWS ==================== */
    --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.3);
    --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.4);
    --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.5);
    --shadow-xl: 0 16px 48px rgba(0, 0, 0, 0.6);
    
    /* ==================== TRANSITIONS ==================== */
    --transition-fast: 0.15s ease;
    --transition-normal: 0.2s ease;
    --transition-slow: 0.3s ease;
    
    /* ==================== Z-INDEX ==================== */
    --z-dropdown: 100;
    --z-sticky: 200;
    --z-fixed: 300;
    --z-modal-backdrop: 400;
    --z-modal: 500;
    --z-popover: 600;
    --z-tooltip: 700;
    --z-toast: 800;
    --z-confirm: 1200;
    
    /* ==================== LAYOUT ==================== */
    --sidebar-width: 248px;
    --sidebar-collapsed-width: 64px;
    --navbar-height: 64px;
    --content-max-width: 1400px;

    /* ==================== BREAKPOINTS ==================== */
    --bp-sm: 640px;
